class DataTable extends Component {
  componentDidMount() {
    this.props.fetchData(this.props.filters)
  }

  componentDidUpdate(prevProps) {
    if (prevProps.filters !== this.props.filters) {
      this.props.fetchData(this.props.filters)
    }
  }

  render() {
    if (this.props.loading) return <Spinner />
    return <Table data={this.props.data} />
  }
}

export default connect(mapStateToProps, { fetchData })(DataTable)

// After: Functional component with React Query
function DataTable({ filters }: { filters: Filters }) {
  const { data, isLoading } = useQuery({
    queryKey: ['tableData', filters],
    queryFn: () => fetchTableData(filters),
    staleTime: 5 * 60 * 1000, // Cache for 5 minutes
  })

  if (isLoading) return <Skeleton className="h-64" />
  return <Table data={data} />
}

import { useTextField } from 'react-aria'
import { useRef, type FC } from 'react'

interface TextFieldProps {
  label: string
  value: string
  onChange: (value: string) => void
  errorMessage?: string
  description?: string
}

export const TextField: FC<TextFieldProps> = (props) => {
  const ref = useRef<HTMLInputElement>(null)
  const { labelProps, inputProps, errorMessageProps, descriptionProps } = useTextField(
    {
      ...props,
      isInvalid: !!props.errorMessage,
    },
    ref
  )

  return (
    <div className="flex flex-col gap-1.5">
      <label {...labelProps} className="text-sm font-medium text-primary">
        {props.label}
      </label>
      <input
        {...inputProps}
        ref={ref}
        className="rounded-lg border border-secondary px-3 py-2 focus:border-brand-500 focus:ring-2 focus:ring-brand-500/20"
      />
      {props.description && (
        <p {...descriptionProps} className="text-sm text-secondary">
          {props.description}
        </p>
      )}
      {props.errorMessage && (
        <p {...errorMessageProps} className="text-sm text-error-600">
          {props.errorMessage}
        </p>
      )}
    </div>
  )
}

import { useButton, useSelect, useSelectState, Item } from 'react-aria'
import { useSelectState as useSelectStateStately } from 'react-stately'
import { ChevronDown } from '@untitledui/icons'

export function Select({ label, items, selectedKey, onSelectionChange }) {
  const state = useSelectStateStately({ 
    items, 
    selectedKey, 
    onSelectionChange 
  })

  const ref = useRef(null)
  const { triggerProps, valueProps, menuProps } = useSelect(
    { label, items },
    state,
    ref
  )

  return (
    <div className="relative">
      <label className="text-sm font-medium text-primary">{label}</label>
      <button
        {...triggerProps}
        ref={ref}
        className="flex w-full items-center justify-between rounded-lg border px-3 py-2"
      >
        <span {...valueProps}>
          {state.selectedItem?.rendered ?? 'Select an option'}
        </span>
        <ChevronDown className="size-4" />
      </button>
      {state.isOpen && (
        <ul {...menuProps} className="absolute mt-1 w-full rounded-lg border bg-primary shadow-lg">
          {[...state.collection].map((item) => (
            <SelectOption key={item.key} item={item} state={state} />
          ))}
        </ul>
      )}
    </div>
  )
}

